\set ON_ERROR_STOP on
SELECT public.report_test_assert(current_database()='moderation_test' OR current_setting('test.dm_disposable',true)='1','disposable direct-message database');
RESET ROLE;
DELETE FROM public.mc_staff_overrides WHERE user_id IN ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000005');
UPDATE auth.sessions SET created_at=clock_timestamp();
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000001','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_test_assert((public.mc_call('conversations')->>'total')::int>=1,'official conversations remain visible to all staff');
SELECT public.mc_call('direct_message','{"requestId":"80000000-0000-0000-0000-000000000001","userId":"00000000-0000-0000-0000-000000000003","subject":"Private check-in","body":"This is a private on-site message for you to read in Moderation Messages."}');
SELECT public.mc_call('direct_message','{"requestId":"80000000-0000-0000-0000-000000000001","userId":"00000000-0000-0000-0000-000000000003","subject":"Private check-in","body":"This is a private on-site message for you to read in Moderation Messages."}');
RESET ROLE;
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_threads WHERE kind='direct')=1,'private message retries save once');
SELECT set_config('test.mc.direct',(SELECT id::text FROM public.mc_threads WHERE kind='direct' LIMIT 1),false);
SELECT public.report_test_assert((SELECT count(*) FROM public.inbox_notifications WHERE kind='moderation_message' AND moderation_thread_id=current_setting('test.mc.direct')::uuid AND message ILIKE '%on-site%')=1,'private message uses the on-site inbox only');
SELECT public.report_test_assert(NOT EXISTS(SELECT 1 FROM public.mc_audit WHERE action='Private message started' AND (details ? 'body' OR details::text ILIKE '%private on-site message%')),'audit omits the private message body');
SET ROLE authenticated;
SELECT public.report_test_assert((public.mc_call('conversation',jsonb_build_object('id',current_setting('test.mc.direct')))->>'kind')='direct','owner can open the private conversation');
SELECT public.report_test_assert((public.mc_call('conversation',jsonb_build_object('id',current_setting('test.mc.direct')))->>'canInvite')::boolean,'owner can invite a second moderator');
SELECT public.report_expect_error($q$SELECT public.mc_call('direct_message','{"requestId":"80000000-0000-0000-0000-000000000002","userId":"00000000-0000-0000-0000-000000000001","subject":"Private check-in","body":"This is a private on-site message for you to read in Moderation Messages."}')$q$,'own account');
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',auth.uid()::text))',current_setting('test.mc.direct')),'already');
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',''00000000-0000-0000-0000-000000000003''))',current_setting('test.mc.direct')),'recipient');
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',''00000000-0000-0000-0000-000000000004''))',current_setting('test.mc.direct')),'staff member');
SELECT public.report_expect_error($q$SELECT public.mc_direct_notice('00000000-0000-0000-0000-000000000003','Subject','This is a private on-site message for you to read in Moderation Messages.')$q$,'permission denied');
SELECT public.report_expect_error($q$SELECT * FROM public.mc_threads$q$,'permission denied');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000002','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_test_assert((public.mc_call('conversations','{"kind":"direct"}')->>'total')::int=0,'uninvited staff cannot list another moderator private thread');
SELECT public.report_expect_error(format('SELECT public.mc_call(''conversation'',jsonb_build_object(''id'',%L))',current_setting('test.mc.direct')),'not found');
SELECT public.report_expect_error(format('SELECT public.mc_call(''staff_reply'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''Uninvited staff cannot reply to this private on-site conversation.''))',current_setting('test.mc.direct')),'not found');
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',''00000000-0000-0000-0000-000000000001''))',current_setting('test.mc.direct')),'not found');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000001','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('invite_staff',jsonb_build_object('requestId','80000000-0000-0000-0000-000000000003','threadId',current_setting('test.mc.direct'),'staffId','00000000-0000-0000-0000-000000000002'));
SELECT public.mc_call('invite_staff',jsonb_build_object('requestId','80000000-0000-0000-0000-000000000003','threadId',current_setting('test.mc.direct'),'staffId','00000000-0000-0000-0000-000000000002'));
RESET ROLE;
SELECT public.report_test_assert((SELECT second_staff_id::text FROM public.mc_threads WHERE id=current_setting('test.mc.direct')::uuid)='00000000-0000-0000-0000-000000000002','invite retries save once');
SET ROLE authenticated;
SELECT public.report_test_assert(NOT (public.mc_call('conversation',jsonb_build_object('id',current_setting('test.mc.direct')))->>'canInvite')::boolean,'a third staff member cannot be invited');
RESET ROLE;
INSERT INTO public.mc_staff_overrides(user_id,role) VALUES('00000000-0000-0000-0000-000000000005','moderator') ON CONFLICT(user_id) DO UPDATE SET role=EXCLUDED.role;
SET ROLE authenticated;
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',''00000000-0000-0000-0000-000000000005''))',current_setting('test.mc.direct')),'already');
RESET ROLE;
SELECT public.report_test_assert(NOT EXISTS(SELECT 1 FROM public.mc_audit WHERE action='Second moderator invited' AND details ? 'body'),'invite audit omits message bodies');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000002','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.report_test_assert((public.mc_call('conversations','{"kind":"direct"}')->>'total')::int=1,'invited moderator can list the private thread');
SELECT public.mc_call('conversation',jsonb_build_object('id',current_setting('test.mc.direct')));
SELECT public.mc_call('staff_reply',jsonb_build_object('requestId','80000000-0000-0000-0000-000000000004','threadId',current_setting('test.mc.direct'),'body','The invited moderator can reply in this private on-site conversation.'));
SELECT public.report_expect_error(format('SELECT public.mc_call(''invite_staff'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''staffId'',''00000000-0000-0000-0000-000000000005''))',current_setting('test.mc.direct')),'who started');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000005';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000005','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_test_assert((public.mc_call('conversations','{"kind":"direct"}')->>'total')::int=0,'a third staff member cannot list the private thread');
SELECT public.report_expect_error(format('SELECT public.mc_call(''conversation'',jsonb_build_object(''id'',%L))',current_setting('test.mc.direct')),'not found');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000003","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('my_inbox')->'threads') t WHERE t->>'id'=current_setting('test.mc.direct'))=1,'recipient sees the private thread in the on-site inbox');
SELECT public.report_test_assert(NOT (public.mc_call('my_thread',jsonb_build_object('id',current_setting('test.mc.direct')))->'messages'->0 ? 'sender_id'),'staff identity is not exposed to the recipient');
SELECT public.report_test_assert(NOT (public.mc_call('my_thread',jsonb_build_object('id',current_setting('test.mc.direct'))) ? 'owner_id') AND NOT (public.mc_call('my_thread',jsonb_build_object('id',current_setting('test.mc.direct'))) ? 'second_staff_id'),'staff identifiers stay off the recipient payload');
SELECT public.mc_call('user_reply',jsonb_build_object('requestId','80000000-0000-0000-0000-000000000005','threadId',current_setting('test.mc.direct'),'body','I received this private on-site message and can reply here.'));
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.report_expect_error(format('SELECT public.mc_call(''my_thread'',jsonb_build_object(''id'',%L))',current_setting('test.mc.direct')),'not found');
RESET ROLE;
CREATE TEMP TABLE direct_counts AS SELECT (SELECT count(*) FROM public.mc_threads WHERE kind='direct') d,(SELECT count(*) FROM public.mc_messages) m,(SELECT count(*) FROM public.inbox_notifications WHERE kind='moderation_message') n;
\ir ../../../supabase/live-site/supabase-moderation-direct-messages.sql
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_threads WHERE kind='direct')=(SELECT d FROM direct_counts),'rerun preserves private threads');
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_messages)=(SELECT m FROM direct_counts),'rerun preserves messages');
SELECT public.report_test_assert((SELECT count(*) FROM public.inbox_notifications WHERE kind='moderation_message')=(SELECT n FROM direct_counts),'rerun preserves on-site inbox rows');
SELECT 'Live moderation private on-site messages tests passed';
